#include <mach/mach.h>
#include <mach/vm_statistics.h>
#include <stdint.h>
#include <stdio.h>
#include <unistd.h>

int main(void) {
    vm_statistics64_data_t stats = {0};
    mach_msg_type_number_t count = HOST_VM_INFO64_COUNT;
    mach_port_t host = mach_host_self();
    kern_return_t status = host_statistics64(host, HOST_VM_INFO64,
        (host_info64_t)&stats, &count);
    mach_port_deallocate(mach_task_self(), host);
    long page_size = sysconf(_SC_PAGESIZE);
    if (status != KERN_SUCCESS || count != HOST_VM_INFO64_COUNT || page_size <= 0) return 1;
    uint64_t credit = (stats.external_page_count < stats.inactive_count ?
        stats.external_page_count : stats.inactive_count) / 2;
    uint64_t available = ((uint64_t)stats.free_count + credit) * (uint64_t)page_size;
    printf("{\"page_size\":%ld,\"free_count\":%u,\"speculative_count\":%u,"
           "\"inactive_count\":%u,\"external_page_count\":%u,\"policy_available_bytes\":%llu}\n",
           page_size, stats.free_count, stats.speculative_count, stats.inactive_count,
           stats.external_page_count, (unsigned long long)available);
    return 0;
}
